use super::{native_appearance_inspection as a,native_appearance_layer_study as layer,native_appearance_replay_study as replay,native_appearance_replay_study_tests as fixture,native_appearance_terrain_study as terrain,native_resources as r,world_map::WorldCell};
use std::{fs,path::{Path,PathBuf},collections::BTreeMap,sync::atomic::AtomicBool};use serde_json::{Value,json};use sha2::{Digest,Sha256};
fn sha(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}fn digest(s:&str)->[u8;32]{(0..32).map(|i|u8::from_str_radix(&s[i*2..i*2+2],16).unwrap()).collect::<Vec<_>>().try_into().unwrap()}fn byte_pin(v:&Value)->r::BytePin{r::BytePin{bytes:v["bytes"].as_u64().unwrap(),sha256:digest(v["sha256"].as_str().unwrap())}}fn pin(path:&Path)->Value{let b=fs::read(path).unwrap();json!({"path":path,"bytes":b.len(),"sha256":sha(&b)})}
fn inputs()->terrain::Inputs{terrain::Inputs{placement:Some(WorldCell{x:32724,y:32784}),static_source_roofs:Some(true),terrain_first:Some(true)}}
#[test]#[ignore = "requires: local evidence roots (snapshot JSON holds absolute D:\\ paths + SHA pins; only runnable on the original machine)"] fn finite_attack47_end72_interleaves_actual_native564_floor_objects_and_player(){
 let project=Path::new(env!("CARGO_MANIFEST_DIR"));let fixed=fixture::Fixed::new();let d=a::nad(&fixed.bytes("resources/appearance-dependencies.nad")).unwrap();let bindings=a::nab(&fixed.bytes("evidence/appearance-bindings.nab")).unwrap();let b=&bindings[3];let trace:Value=serde_json::from_slice(&fixed.bytes("appearance-layer-trace.json")).unwrap();let banks=BTreeMap::from([(88,fixed.bank(&d,&trace,88)),(72,fixed.bank(&d,&trace,72))]);
 let provider_path=project.join("target/r425-native-dm564-fixture/consumer-input.json");let provider:Value=serde_json::from_slice(&fs::read(&provider_path).unwrap()).unwrap();let archives=provider["archive_pins"].as_array().unwrap();let map_path=PathBuf::from(provider["native_map"]["path"].as_str().unwrap());let roots=r::NativeSources{map_root:map_path.parent().unwrap().parent().unwrap().to_owned(),archive_root:PathBuf::from(archives[0]["path"].as_str().unwrap()).parent().unwrap().to_owned()};let plan=r::NativeAssetPlan{namespace:r::ResourceNamespace::NativeLitoV1,map_id:564,canonical_sha256:digest(provider["native_map"]["canonical_sha256"].as_str().unwrap()),sectors:vec![r::SectorPin{key:r::NativeSectorKey{map_id:564,x:0x7fff,y:0x8000},pin:byte_pin(&provider["native_map"])}],archives:archives.iter().zip([r::ArchiveRole::TileIndex,r::ArchiveRole::TilePak,r::ArchiveRole::SpriteIndex,r::ArchiveRole::SpritePak]).map(|(v,role)|r::ArchivePin{role,pin:byte_pin(v)}).collect()};let assets=r::NativeResourceAdapter::pinned_inspection().load_static(&roots,&plan,Default::default(),&AtomicBool::new(false)).unwrap();let mut world=terrain::Terrain::new(true,b,b,b.observed,&assets,&plan,7).unwrap();let(floor_refs,object_refs)=world.draw_counts();assert!(floor_refs>0&&object_refs>0);let layers=layer::Model::new(true,b,b,b.observed,7).unwrap();let mut action=replay::Replay::new(true,&d,b,b,b.observed,0,fixture::ordinary(),fixture::end()).unwrap();
 let out=project.join("target/r451-finite-terrain-player-cpu");fs::create_dir_all(&out).unwrap();let mut rows=Vec::new();let mut images=Vec::new();for expected in [1,2,3,4,5,6,0]{let(index,number,subframe,due)=action.next(b,b.observed).unwrap();assert_eq!(index,expected);let bank=&banks[&number];let list=layers.submissions(b,b.observed,number,subframe as usize,&bank.body,&bank.shadow,&bank.layer,fixture::inputs()).unwrap();
  for selector in 0..3{let mut q=inputs();match selector{0=>q.placement=None,1=>q.static_source_roofs=None,_=>q.terrain_first=None};assert!(world.render(b,b.observed,&list,q).is_err());assert_eq!(action.next(b,b.observed).unwrap(),(index,number,subframe,due));}
  let f=world.render(b,b.observed,&list,inputs()).unwrap();assert!(f.visible_terrain_references>0&&f.body_visible_pixels>0);let state=action.sample(b,b.observed,due,bank,fixture::inputs()).unwrap();assert_eq!((state.catalog_frame,state.bank,state.subframe),(index,number,subframe));images.push(fixture::png(&out.join(format!("attack47-frame{index}-bank{number}-sub{subframe}-native564.png")),f.canvas.rgba(),512,384));rows.push(json!({"catalog_frame":index,"bank":number,"subframe":subframe,"dispatch_ms":state.dispatch_ms,"next_due_ms":state.next_due_ms,"ended":state.ended,"body_visible_pixels":f.body_visible_pixels,"visible_terrain_references":f.visible_terrain_references,"RGBA_sha256":sha(f.canvas.rgba())}));}
 assert!(action.next(b,b.observed).is_err());let bank=&banks[&72];let list=layers.submissions(b,b.observed,72,0,&bank.body,&bank.shadow,&bank.layer,fixture::inputs()).unwrap();assert!(world.render(b,b.observed,&list,inputs()).is_err());world.retire();assert!(terrain::Terrain::new(false,b,b,b.observed,&assets,&plan,1).is_err());let mut extra=vec![pin(&provider_path),pin(&map_path)];for v in archives{extra.push(pin(Path::new(v["path"].as_str().unwrap())));}
 fs::write(project.join("logs/continuation-20261003/r451-terrain-details.json"),serde_json::to_vec_pretty(&json!({"state":"FINITE_CONDITIONAL_ATTACK47_WITH_ACTUAL_NATIVE564_STATIC_TERRAIN_END72_STOP","rows":rows,"CPU_frames":7,"floor_source_references":floor_refs,"object_source_references":object_refs,"input_pins":fixed.used.into_inner(),"extra_input_pins":extra,"images":images,"logical_map":564,"conditional_player_cell":[32724,32784],"static_source_roof_policy":true,"Layer8_effect_animation_included":false,"runtime_roof_state_observed":false,"runtime_inputs_observed":false,"idle_callback_executed":false,"renderer_LOADED":false,"GUI":0})).unwrap()).unwrap();
}
